// Compiles an assigned-weight PixelNet into a GPU kernel (GLSL ES 3.0) or a
// CPU kernel (JavaScript), and evaluates the hypernetwork each frame.
//
// * Zero weights are never emitted: the kernel is the sparse network itself.
// * Constant weights become literals (the GPU compiler folds them); weights
//   generated by the hypernetwork live in a uniform buffer (std140 vec4[]).
// * Each output-stage expert (layer) is wrapped in a uniform branch on its
//   opacity, and every hidden neuron is placed in the block of the experts that
//   consume it, so experts that are off cost nothing for the whole frame
//   (conditional computation, as in a mixture of experts).
import { Param, PixelNet, type Act, type Neuron } from "./graph";

export const ALPHA_EPS = 1 / 1024;
const TAU = Math.PI * 2;

interface Slot { p: Param; wrap: boolean }

export interface CostStats {
  neurons: number;     // hidden neurons evaluated per pixel
  macs: number;        // multiply-accumulates per pixel
  transcendental: number; // sin / exp / sqrt / reciprocal per pixel
  activeLayers: number;
  totalLayers: number;
}

export interface Compiled {
  glsl: string;
  /** number of vec4 in the parameter uniform buffer */
  vec4s: number;
  /** run the hypernetwork: fills the uniform buffer for this frame */
  update(inputs: Record<string, number>): Float32Array;
  /** per-pixel cost for the last update() */
  cost(): CostStats;
  /** totals for the network independent of the frame */
  size: { neurons: number; synapses: number; layers: number; dynamicParams: number; frameUnits: number };
  /** generated JS source of the CPU kernel */
  jsSrc: string;
  /** CPU kernel: renders RGBA8 into out (row 0 = top) */
  renderCPU(out: Uint8ClampedArray, W: number, H: number, aa?: number): void;
  /** spectral bank table as an RGBA32F texture: width 2K texels, one row per bank */
  bankTex: { data: Float32Array; width: number; height: number };
  /** reference interpreter for one pixel (tests): uv in [0,1]², returns linear RGB after grading */
  reference(u: number, v: number, aa: number): [number, number, number];
  net: PixelNet;
}

const ACT_TRANSCENDENTAL: Partial<Record<Act, number>> = { sin: 1, sig: 1, edge: 1, rcp: 1, sqrt: 1, tanh: 1, gauss: 1 };

export function compile(net: PixelNet): Compiled {
  const F = net.F;
  const N = net.neurons;
  const L = net.layers;

  // ---------------------------------------------------------- parameter slots
  const slots: Slot[] = [];
  const slotIdx = new Map<string, number>();
  const slotOf = (p: Param, wrap = false): number => {
    const key = p.key() + (wrap ? "~" : "");
    let i = slotIdx.get(key);
    if (i === undefined) {
      i = slots.push({ p, wrap }) - 1;
      slotIdx.set(key, i);
    }
    return i;
  };

  // ---------------------------------------------------------- liveness / placement
  const deadLayer = L.map((l) => l.alpha.isConst && l.alpha.c <= ALPHA_EPS);
  const ALWAYS = -1;
  const cons: Set<number>[] = N.map(() => new Set());
  L.forEach((l, j) => {
    if (deadLayer[j]) return;
    if (l.gate >= 0) cons[l.gate].add(j);
    if (l.shade >= 0) cons[l.shade].add(j);
  });
  if (net.vignette >= 0) cons[net.vignette].add(ALWAYS);
  const srcs = (n: Neuron) => (n.act === "prod" || n.act === "bank2" ? [n.pa!, n.pb!] : n.in.map((t) => t.src));
  for (let i = N.length - 1; i >= 0; i--) {
    for (const s of srcs(N[i])) {
      if (s >= i) throw new Error(`neuron ${i} depends on later neuron ${s}`);
      for (const c of cons[i]) cons[s].add(c);
    }
  }
  const FIRST_HIDDEN = 5;
  const top: number[] = [];
  const own: number[][] = L.map(() => []);
  const shared: number[][] = L.map(() => []); // emitted before layer j (its first consumer)
  for (let i = FIRST_HIDDEN; i < N.length; i++) {
    const c = cons[i];
    if (!c.size) continue;
    if (c.has(ALWAYS)) top.push(i);
    else if (c.size === 1) own[[...c][0]].push(i);
    else {
      if (N[i].act === "bank" || N[i].act === "bank2") throw new Error("bank neurons must belong to one expert");
      shared[Math.min(...c)].push(i);
    }
  }

  // ---------------------------------------------------------- spectral banks
  const KB = Math.max(1, net.bankK);
  const rows = Math.max(1, net.banks.length);
  const bankFlat = new Float32Array(rows * KB * 5);
  const bankTexData = new Float32Array(rows * KB * 8);
  net.banks.forEach((modes, r) => {
    for (let k = 0; k < Math.min(KB, modes.length); k++) {
      const [wx, wy, phi, a, b] = modes[k];
      bankFlat.set([wx, wy, phi, a, b], (r * KB + k) * 5);
      bankTexData.set([wx, wy, phi, a, b, 0, 0, 0], (r * KB + k) * 8);
    }
  });

  // ---------------------------------------------------------- code generation
  interface Dialect {
    num(v: number): string; slot(k: number): string; decl: string;
    sin: string; exp: string; abs: string; max: string; sqrt: string; tanh: string; clamp(s: string): string;
  }
  const fnum = (v: number, glsl: boolean) => {
    let s = Number.isInteger(v) ? v.toFixed(1) : v.toPrecision(8);
    if (!glsl) s = String(+s);
    return v < 0 ? `(${s})` : s;
  };
  const GLSL: Dialect = {
    num: (v) => fnum(v, true), slot: (k) => `P[${k >> 2}].${"xyzw"[k & 3]}`, decl: "float",
    sin: "sin", exp: "exp", abs: "abs", max: "max", sqrt: "sqrt", tanh: "tanh", clamp: (s) => `clamp(${s},0.,1.)`,
  };
  const JS: Dialect = {
    num: (v) => fnum(v, false), slot: (k) => `P[${k}]`, decl: "const",
    sin: "Math.sin", exp: "Math.exp", abs: "Math.abs", max: "Math.max", sqrt: "Math.sqrt", tanh: "Math.tanh",
    clamp: (s) => `Math.min(1,Math.max(0,${s}))`,
  };
  const pexpr = (d: Dialect, p: Param, wrap = false) => (p.isConst ? d.num(p.c) : d.slot(slotOf(p, wrap)));

  const neuronExpr = (d: Dialect, i: number): string => {
    const n = N[i];
    if (n.act === "prod") return `n${n.pa}*n${n.pb}`;
    if (n.act === "bank") return d === GLSL ? `bank(${n.bankRow},n${n.in[0].src},n${n.in[1].src})` : `bank(${n.bankRow},n${n.in[0].src},n${n.in[1].src})`;
    if (n.act === "bank2") return d === GLSL ? `b${n.pa}.y` : `bk${n.pa}`;
    const parts: string[] = [];
    for (const t of n.in) {
      if (t.w.isConst && t.w.c === 1) parts.push(`n${t.src}`);
      else parts.push(`${pexpr(d, t.w)}*n${t.src}`);
    }
    let s = parts.length ? parts.join("+") : d.num(0);
    if (n.g && !(n.g.isConst && n.g.c === 1)) s = `${pexpr(d, n.g)}*(${s})`;
    if (!(n.b.isConst && n.b.c === 0)) s += "+" + pexpr(d, n.b, n.act === "sin");
    switch (n.act) {
      case "lin": return s;
      case "sin": return `${d.sin}(${s})`;
      case "sig": return `1./(1.+${d.exp}(-(${s})))`;
      case "edge": return `1./(1.+${d.exp}(-aa*(${s})))`;
      case "abs": return `${d.abs}(${s})`;
      case "rcp": return `1./${d.max}(${s},.01)`;
      case "relu": return `${d.max}(${s},0.)`;
      case "clip": return d.clamp(s);
      case "sqrt": return `${d.sqrt}(${d.max}(${s},0.))`;
      case "tanh": return `${d.tanh}(${s})`;
      case "gauss": return `${d.exp}(-(${s})*(${s}))`;
      default: throw new Error("bad act " + n.act);
    }
  };

  const emit = (d: Dialect): string[] => {
    const out: string[] = [];
    const isG = d === GLSL;
    const declared = new Set<number>();
    const line = (ind: string, i: number) => {
      declared.add(i);
      if (N[i].act === "bank") {
        return isG ? `${ind}vec2 b${i}=${neuronExpr(d, i)}; float n${i}=b${i}.x;`
          : `${ind}${neuronExpr(d, i)}; const n${i}=BK[0], bk${i}=BK[1];`;
      }
      return `${ind}${d.decl} n${i}=${neuronExpr(d, i)};`;
    };
    for (const i of top) out.push(line("  ", i));
    L.forEach((l, j) => {
      if (deadLayer[j]) return;
      const A = pexpr(d, l.alpha);
      const guardOf = (js: number[]) => js.some((k) => L[k].alpha.isConst) ? "" :
        js.map((k) => `${pexpr(d, L[k].alpha)}>${d.num(ALPHA_EPS)}`).join("||");
      if (shared[j].length) {
        // shared neurons: declared at function scope, computed if any consumer is on
        const g = guardOf([...new Set(shared[j].flatMap((i) => [...cons[i]]))]);
        for (const i of shared[j]) out.push(`  ${isG ? "float" : "let"} n${i}=0.;`);
        out.push(g ? `  if(${g}){` : "  {");
        for (const i of shared[j]) { declared.add(i); out.push(`    n${i}=${neuronExpr(d, i)};`); }
        out.push("  }");
      }
      out.push(`  // expert ${j}: ${l.name}`);
      out.push(l.alpha.isConst ? "  {" : `  if(${A}>${d.num(ALPHA_EPS)}){`);
      for (const i of own[j]) out.push(line("    ", i));
      const g = l.gate >= 0 ? `n${l.gate}` : d.num(1);
      const sh = l.shade >= 0 ? `n${l.shade}` : null;
      const ch = (k: number) => {
        const a = pexpr(d, l.c0[k]);
        if (!sh || l.c0[k].key() === l.c1[k].key()) return a;
        return `(${a}+(${pexpr(d, l.c1[k])}-${a})*${sh})`;
      };
      if (isG) {
        out.push(`    vec3 lc=vec3(${ch(0)},${ch(1)},${ch(2)});`);
        if (l.add) out.push(`    col+=lc*(${A}*${g});`);
        else out.push(`    col=mix(col,lc,clamp(${A}*${g},0.,1.));`);
      } else {
        out.push(`    const lr=${ch(0)},lg=${ch(1)},lb=${ch(2)};`);
        if (l.add) out.push(`    const ga=${A}*${g}; cr+=lr*ga; cg+=lg*ga; cb+=lb*ga;`);
        else out.push(`    const ga=Math.min(1,Math.max(0,${A}*${g})); cr+=(lr-cr)*ga; cg+=(lg-cg)*ga; cb+=(lb-cb)*ga;`);
      }
      out.push("  }");
    });
    return out;
  };

  const M = net.grade.M, O = net.grade.o;
  const vig = net.vignette >= 0 ? `n${net.vignette}` : "1.";
  const gBody = emit(GLSL);
  const row = (r: number) => `dot(vec3(${pexpr(GLSL, M[r * 3])},${pexpr(GLSL, M[r * 3 + 1])},${pexpr(GLSL, M[r * 3 + 2])}),col)+${pexpr(GLSL, O[r])}`;
  const gRows = [row(0), row(1), row(2)];
  const jBody = emit(JS);
  const jrow = (r: number) => `${pexpr(JS, M[r * 3])}*cr+${pexpr(JS, M[r * 3 + 1])}*cg+${pexpr(JS, M[r * 3 + 2])}*cb+${pexpr(JS, O[r])}`;
  const jRows = [jrow(0), jrow(1), jrow(2)];
  // all parameters are allocated: size the uniform buffer
  const vec4s = Math.max(1, Math.ceil(slots.length / 4));
  const glsl = `#version 300 es
precision highp float;
// generated by src/render/neural/compile.ts from the assigned-weight network in design.ts
layout(std140) uniform Params { vec4 P[${vec4s}]; };
uniform vec2 R; uniform float asp; uniform float aa;
uniform highp sampler2D BANK;
out vec4 o;
const int KB = ${KB};
vec2 bank(int row, float u, float v){
  vec2 acc = vec2(0.);
  for (int k = 0; k < KB; k++) {
    vec4 m = texelFetch(BANK, ivec2(2*k, row), 0);
    float b = texelFetch(BANK, ivec2(2*k+1, row), 0).x;
    acc += sin(m.x*u + m.y*v + m.z) * vec2(m.w, b);
  }
  return acc;
}
void main(){
  vec2 uv = gl_FragCoord.xy / R;
  float n0=(uv.x-.5)*asp, n1=uv.y, n2=n0*n0, n3=n1*n1, n4=n0*n1;
  vec3 col = vec3(0.);
${gBody.join("\n")}
  vec3 g = vec3(${gRows.join(", ")}) * ${vig};
  o = vec4(pow(clamp(g,0.,1.), vec3(.95)), 1.);
}`;

  const jsSrc = `
const BK = new Float64Array(2);
function bank(row, u, v) {
  let a = 0, b = 0;
  const o = row * KB * 5;
  for (let k = 0; k < KB; k++) {
    const q = o + k * 5, s = Math.sin(B[q] * u + B[q + 1] * v + B[q + 2]);
    a += B[q + 3] * s; b += B[q + 4] * s;
  }
  BK[0] = a; BK[1] = b;
}
for (let py=0; py<H; py++) {
  const n1=(H-py-.5)/H, n3=n1*n1;
  for (let px=0; px<W; px++) {
    const n0=((px+.5)/W-.5)*asp, n2=n0*n0, n4=n0*n1;
    let cr=0, cg=0, cb=0;
${jBody.join("\n")}
    const vg=${vig};
    const o=(py*W+px)*4;
    out[o]=255*Math.pow(Math.min(1,Math.max(0,(${jRows[0]})*vg)),.95);
    out[o+1]=255*Math.pow(Math.min(1,Math.max(0,(${jRows[1]})*vg)),.95);
    out[o+2]=255*Math.pow(Math.min(1,Math.max(0,(${jRows[2]})*vg)),.95);
    out[o+3]=255;
  }
}`;
  type Kernel = (out: Uint8ClampedArray, W: number, H: number, P: Float32Array, asp: number, aa: number, B: Float32Array, KB: number) => void;
  let jsKernel: Kernel | null = null;

  // ---------------------------------------------------------- per-frame update
  const P = new Float32Array(vec4s * 4);
  const P64 = new Float64Array(slots.length);
  let fv = new Float64Array(F.units.length);
  let asp = 16 / 9;
  const evalP = (p: Param) => { let s = p.c; for (const [u, k] of p.t) s += k * fv[u]; return s; };
  const update = (inputs: Record<string, number>) => {
    if (fv.length !== F.units.length) fv = new Float64Array(F.units.length);
    F.run(inputs, fv);
    asp = inputs.asp ?? asp;
    for (let k = 0; k < slots.length; k++) {
      let v = evalP(slots[k].p);
      if (slots[k].wrap) v -= TAU * Math.floor(v / TAU + 0.5);
      P64[k] = v;
      P[k] = v;
    }
    return P;
  };

  // ---------------------------------------------------------- cost model
  const nCost = (i: number) => {
    const n = N[i];
    if (n.act === "bank") return { macs: 5 * KB, tr: KB };
    if (n.act === "bank2") return { macs: 0, tr: 0 };
    return { macs: n.act === "prod" ? 1 : n.in.length, tr: ACT_TRANSCENDENTAL[n.act] ?? 0 };
  };
  const cost = (): CostStats => {
    const on = L.map((l, j) => !deadLayer[j] && evalP(l.alpha) > ALPHA_EPS);
    let neurons = 0, macs = 0, tr = 0;
    const take = (i: number) => { const c = nCost(i); neurons++; macs += c.macs; tr += c.tr; };
    top.forEach(take);
    L.forEach((_, j) => {
      if (!on[j]) return;
      own[j].forEach(take);
      macs += 9; // colour mix + compositing
    });
    const sharedAll = shared.flat();
    for (const i of sharedAll) if ([...cons[i]].some((j) => on[j])) take(i);
    macs += 12; // grading
    return { neurons, macs, transcendental: tr, activeLayers: on.filter(Boolean).length, totalLayers: L.length };
  };

  let synapses = 0, live = 0;
  for (let i = FIRST_HIDDEN; i < N.length; i++) if (cons[i].size) { live++; synapses += nCost(i).macs; }

  // ---------------------------------------------------------- reference interpreter
  const reference = (u: number, v: number, aa: number): [number, number, number] => {
    const val = new Float64Array(N.length), bankB = new Float64Array(N.length);
    const x = (u - 0.5) * asp, y = v;
    val[0] = x; val[1] = y; val[2] = x * x; val[3] = y * y; val[4] = x * y;
    for (let i = FIRST_HIDDEN; i < N.length; i++) {
      const n = N[i];
      if (n.act === "prod") { val[i] = val[n.pa!] * val[n.pb!]; continue; }
      if (n.act === "bank") {
        const u = val[n.in[0].src], v = val[n.in[1].src];
        let a = 0, b = 0;
        for (const [wx, wy, phi, ka, kb] of net.banks[n.bankRow!].slice(0, KB)) {
          const s = Math.sin(Math.fround(wx) * u + Math.fround(wy) * v + Math.fround(phi));
          a += Math.fround(ka) * s; b += Math.fround(kb) * s;
        }
        val[i] = a; bankB[i] = b;
        continue;
      }
      if (n.act === "bank2") { val[i] = bankB[n.pa!]; continue; }
      let s = 0;
      for (const t of n.in) s += evalP(t.w) * val[t.src];
      if (n.g) s *= evalP(n.g);
      s += evalP(n.b);
      const a = n.act;
      val[i] = a === "lin" ? s : a === "sin" ? Math.sin(s) : a === "sig" ? 1 / (1 + Math.exp(-s)) :
        a === "edge" ? 1 / (1 + Math.exp(-aa * s)) : a === "abs" ? Math.abs(s) : a === "rcp" ? 1 / Math.max(s, 0.01) :
        a === "relu" ? Math.max(s, 0) : a === "clip" ? Math.min(1, Math.max(0, s)) : a === "tanh" ? Math.tanh(s) :
        a === "gauss" ? Math.exp(-s * s) : Math.sqrt(Math.max(s, 0));
    }
    const c = [0, 0, 0];
    L.forEach((l, j) => {
      if (deadLayer[j]) return;
      const A = evalP(l.alpha);
      if (A <= ALPHA_EPS) return;
      const g = l.gate >= 0 ? val[l.gate] : 1;
      const sh = l.shade >= 0 ? val[l.shade] : 0;
      for (let k = 0; k < 3; k++) {
        const c0 = evalP(l.c0[k]), lc = c0 + (evalP(l.c1[k]) - c0) * sh;
        if (l.add) c[k] += lc * A * g;
        else c[k] += (lc - c[k]) * Math.min(1, Math.max(0, A * g));
      }
    });
    const vg = net.vignette >= 0 ? val[net.vignette] : 1;
    return [0, 1, 2].map((r) => (evalP(M[r * 3]) * c[0] + evalP(M[r * 3 + 1]) * c[1] + evalP(M[r * 3 + 2]) * c[2] + evalP(O[r])) * vg) as [number, number, number];
  };

  return {
    glsl, vec4s, update, cost, net, reference,
    bankTex: { data: bankTexData, width: 2 * KB, height: rows },
    size: { neurons: live, synapses, layers: L.length, dynamicParams: slots.length, frameUnits: F.units.length },
    jsSrc,
    renderCPU(out, W, H, aaGain = 2.2 * H) {
      jsKernel ??= new Function("out", "W", "H", "P", "asp", "aa", "B", "KB", jsSrc) as Kernel;
      jsKernel(out, W, H, P, asp, aaGain, bankFlat, KB);
    },
  };
}
